import React, { useState, useEffect } from 'react';
import Calendar from 'react-calendar';
import 'react-calendar/dist/Calendar.css'; // Import calendar base styles
import './AttendancePage.css'; // Our custom styles
import axios from 'axios';
import moment from 'moment';

// This function simulates a full month of time logs based on your real employee list
const createMockTimeLogs = (employees) => {
    const logs = [];
    if (!Array.isArray(employees)) return logs;

    employees.forEach(employee => {
        for (let day = 1; day <= 28; day++) { // Simulate for a month
            const statusOptions = ['Present', 'Absent', 'On Leave', 'Half Day', 'Present', 'Present'];
            const status = statusOptions[Math.floor(Math.random() * statusOptions.length)];

            // Only create a log if the person wasn't absent or on leave
            if (status !== 'Absent' && status !== 'On Leave') {
                logs.push({
                    id: `${employee.id}-${day}`,
                    employee: employee,
                    date: `2025-10-${String(day).padStart(2, '0')}`,
                    clockIn: '09:' + String(day % 15).padStart(2, '0') + ' AM',
                    clockOut: status === 'Half Day' ? '01:00 PM' : `05:${String(day * 2).padStart(2, '0')} PM`,
                    status,
                });
            } else {
                 logs.push({ // Still add a log for absent/leave to color the calendar
                    id: `${employee.id}-${day}`,
                    employee: employee,
                    date: `2025-10-${String(day).padStart(2, '0')}`,
                    status,
                });
            }
        }
    });
    return logs;
};

const AttendancePage = () => {
  const [employees, setEmployees] = useState([]);
  const [allTimeLogs, setAllTimeLogs] = useState([]);
  const [isLoading, setIsLoading] = useState(true);

  const [selectedEmployeeId, setSelectedEmployeeId] = useState('All');
  const [selectedDate, setSelectedDate] = useState(new Date());

  // Fetch employees and generate mock logs
  useEffect(() => {
    const fetchAndPrepareData = async () => {
      setIsLoading(true);
      try {
        const response = await axios.get('http://127.0.0.1:8000/api/employees/');
        const employeesData = response.data.results || response.data || [];
        setEmployees(employeesData);

        if (employeesData.length > 0) {
            setAllTimeLogs(createMockTimeLogs(employeesData));
        }
      } catch (error) {
        console.error("Failed to fetch employees:", error);
      } finally {
        setIsLoading(false);
      }
    };
    fetchAndPrepareData();
  }, []);

  // Filter logs for the selected employee to color their calendar
  const employeeCalendarLogs = allTimeLogs.filter(log => 
    selectedEmployeeId === 'All' || log.employee.id === parseInt(selectedEmployeeId)
  );

  // Filter logs for the detailed table below based on the clicked date
  const dailyLogs = allTimeLogs.filter(log => 
    moment(log.date).isSame(selectedDate, 'day') &&
    (selectedEmployeeId === 'All' || log.employee.id === parseInt(selectedEmployeeId))
  );

  const tileClassName = ({ date, view }) => {
    if (view === 'month' && selectedEmployeeId !== 'All') {
      const dateString = moment(date).format('YYYY-MM-DD');
      const logForDay = employeeCalendarLogs.find(log => log.date === dateString);
      if (logForDay) {
        return `day-${logForDay.status.toLowerCase().replace(' ', '-')}`;
      }
    }
    return null;
  };

  return (
    <div className="p-8">
      <div className="flex justify-between items-center mb-6">
        <div>
          <h1 className="text-3xl font-bold">Attendance Calendar</h1>
          <p className="text-sm text-subtext-light">View monthly attendance based on time tracking data.</p>
        </div>
        <div className="w-full max-w-xs">
          <label htmlFor="employee-select" className="block text-sm font-medium text-subtext-light mb-1">View For</label>
          <select 
            id="employee-select"
            value={selectedEmployeeId}
            onChange={(e) => setSelectedEmployeeId(e.target.value)}
            className="w-full bg-card-light dark:bg-gray-800 border-border-light rounded-md shadow-sm"
          >
            <option value="All">All Employees (Summary)</option>
            {employees.map(emp => (
              <option key={emp.id} value={emp.id}>{emp.firstName} {emp.lastName}</option>
            ))}
          </select>
        </div>
      </div>

      <div className="bg-card-light dark:bg-card-dark p-4 rounded-xl shadow-sm">
        <Calendar
          onChange={setSelectedDate}
          value={selectedDate}
          tileClassName={tileClassName}
          className="w-full border-none"
        />
      </div>

      <div className="mt-8">
        <h3 className="text-xl font-semibold mb-4">
          Logs for {moment(selectedDate).format('MMMM Do, YY YY')}
        </h3>
        <DailyLogTable logs={dailyLogs} isLoading={isLoading} />
      </div>
    </div>
  );
};

// --- HELPER COMPONENT FOR THE DAILY LOG TABLE ---
const DailyLogTable = ({ logs, isLoading }) => {
    if (isLoading) return <div className="text-center py-8 text-subtext-light bg-card-light rounded-lg">Loading...</div>;
    if (logs.length === 0) return <div className="text-center py-8 text-subtext-light bg-card-light rounded-lg">No records found for this day.</div>;

    return (
        <div className="bg-card-light dark:bg-card-dark rounded-xl shadow-sm overflow-x-auto">
            <table className="w-full text-sm text-left">
                <thead className="text-xs uppercase bg-background-light">
                    <tr>
                        <th className="px-6 py-3">Employee</th>
                        <th className="px-6 py-3">Clock In</th>
                        <th className="px-6 py-3">Clock Out</th>
                        <th className="px-6 py-3">Status</th>
                    </tr>
                </thead>
                <tbody>
                    {logs.map(log => (
                        <tr key={log.id} className="border-b">
                            <td className="px-6 py-4 font-medium">{log.employee.firstName} {log.employee.lastName}</td>
                            <td className="px-6 py-4">{log.clockIn || '--:--'}</td>
                            <td className="px-6 py-4">{log.clockOut || '--:--'}</td>
                            <td className="px-6 py-4">
                               <span className={`px-2 py-1 text-xs font-semibold rounded-full day-${log.status.toLowerCase().replace(' ', '-')}`}>{log.status}</span>
                            </td>
                        </tr>
                    ))}
                </tbody>
            </table>
        </div>
    );
};

export default AttendancePage;
